<?php
declare(strict_types=1);

session_start();
require __DIR__ . '/archive_lib.php';
$_SESSION['csrf_token'] ??= bin2hex(random_bytes(32));

$query = trim((string) ($_GET['q'] ?? ''));
$database = archiveDatabase();
if ($query === '') {
    $documents = $database->query('SELECT id, title, category, tags, original_name, document_date, created_at, length(indexed_text) AS text_size FROM documents ORDER BY created_at DESC LIMIT 50')->fetchAll(PDO::FETCH_ASSOC);
} else {
    $like = '%' . $query . '%';
    $statement = $database->prepare('SELECT id, title, category, tags, original_name, document_date, created_at, length(indexed_text) AS text_size FROM documents WHERE title LIKE ? OR category LIKE ? OR tags LIKE ? OR description LIKE ? OR indexed_text LIKE ? OR original_name LIKE ? ORDER BY created_at DESC LIMIT 100');
    $statement->execute([$like, $like, $like, $like, $like, $like]);
    $documents = $statement->fetchAll(PDO::FETCH_ASSOC);
}
?>
