<body><?php require __DIR__ . '/ui_nav.php'; ?><main id="main-content" tabindex="-1"><nav class="breadcrumb"><a href="index.php">Accueil</a> / <span>Archives</span></nav><section class="hero"><h1>Archives documentaires</h1><p class="intro">Classez vos documents et retrouvez-les facilement.</p></section><?php if (isset($_GET['success'])): ?><p class="notice">Document archive et indexe avec succes.</p><?php endif; ?><div class="grid"><section class="card"><h2>Archiver un document</h2><form action="archive_store.php" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($_SESSION['csrf_token'], ENT_QUOTES, 'UTF-8') ?>"><label>Document</label><input type="file" name="document" accept="application/pdf,image/*,.docx,.xlsx,.xls" capture="environment" required><p class="intro">PDF et images issus d un scanner, Word ou Excel. Maximum 25 Mo.</p><label>Titre</label><input name="title" maxlength="200" placeholder="Titre du document"><label>Categorie</label><input name="category" maxlength="100" placeholder="Suggestion automatique si vide"><label>Mots cles</label><input name="tags" maxlength="500" placeholder="Exemple : RH, contrat, 2026"><label>Date du document</label><input type="date" name="document_date"><label>Description</label><textarea name="description" maxlength="2000"></textarea><button type="submit">Archiver et indexer</button></form></section><section class="card"><h2>Rechercher dans les archives</h2><form class="search" method="get"><input name="q" value="<?= htmlspecialchars($query, ENT_QUOTES, 'UTF-8') ?>" placeholder="Titre, mot cle, contenu PDF, categorie..."><button>Rechercher</button></form><p class="intro"><?= count($documents) ?> document(s) affiche(s).</p><?php foreach ($documents as $document): ?><article class="doc"><div><h3><?= htmlspecialchars($document['title'], ENT_QUOTES, 'UTF-8') ?> <span class="badge"><?= htmlspecialchars($document['category'], ENT_QUOTES, 'UTF-8') ?></span></h3><p><?= htmlspecialchars($document['original_name'], ENT_QUOTES, 'UTF-8') ?> · <?= htmlspecialchars($document['tags'], ENT_QUOTES, 'UTF-8') ?> · <?= $document['text_size'] > 0 ? 'texte indexe' : 'metadonnees indexees' ?></p></div><a class="open" href="archive_download.php?id=<?= (int) $document['id'] ?>" target="_blank">Ouvrir</a></article><?php endforeach; ?></section></div></main><script src="assets/app.js"></script></body></html>
